-- Restore the original six section headings in the flattened Black Friday article without rewriting any prose.
update public.blog_posts
set
  content = replace(replace(replace(replace(replace(replace(content, "پیش از حراج‌ها: جمعه‌ی سیاهِ بازار طلای آمریکا در ۱۸۶۹", E'\\n\\n## پیش از حراج‌ها: جمعه‌ی سیاهِ بازار طلای آمریکا در ۱۸۶۹\\n\\n'), "فیلادلفیا؛ جایی که نام بلک فرایدی معنای امروزی‌اش رو پیدا کرد", E'\\n\\n## فیلادلفیا؛ جایی که نام بلک فرایدی معنای امروزی‌اش رو پیدا کرد\\n\\n'), "چرا فروشگاه‌ها می‌خواستن اسم «جمعه‌ی سیاه» رو عوض کنن؟", E'\\n\\n## چرا فروشگاه‌ها می‌خواستن اسم «جمعه‌ی سیاه» رو عوض کنن؟\\n\\n'), "روایت «از ضرر به سود» از کجا اومد؟", E'\\n\\n## روایت «از ضرر به سود» از کجا اومد؟\\n\\n'), "چطور بلک فرایدی از یک روز آمریکایی به رویدادی جهانی تبدیل شد؟", E'\\n\\n## چطور بلک فرایدی از یک روز آمریکایی به رویدادی جهانی تبدیل شد؟\\n\\n'), "بلک فرایدی امروز؛ یک مناسبت با دو تاریخ متفاوت", E'\\n\\n## بلک فرایدی امروز؛ یک مناسبت با دو تاریخ متفاوت\\n\\n'),
  published_snapshot = jsonb_set(
    coalesce(published_snapshot, '{}'::jsonb),
    '{content}',
    to_jsonb(replace(replace(replace(replace(replace(replace(published_snapshot->>'content', "پیش از حراج‌ها: جمعه‌ی سیاهِ بازار طلای آمریکا در ۱۸۶۹", E'\\n\\n## پیش از حراج‌ها: جمعه‌ی سیاهِ بازار طلای آمریکا در ۱۸۶۹\\n\\n'), "فیلادلفیا؛ جایی که نام بلک فرایدی معنای امروزی‌اش رو پیدا کرد", E'\\n\\n## فیلادلفیا؛ جایی که نام بلک فرایدی معنای امروزی‌اش رو پیدا کرد\\n\\n'), "چرا فروشگاه‌ها می‌خواستن اسم «جمعه‌ی سیاه» رو عوض کنن؟", E'\\n\\n## چرا فروشگاه‌ها می‌خواستن اسم «جمعه‌ی سیاه» رو عوض کنن؟\\n\\n'), "روایت «از ضرر به سود» از کجا اومد؟", E'\\n\\n## روایت «از ضرر به سود» از کجا اومد؟\\n\\n'), "چطور بلک فرایدی از یک روز آمریکایی به رویدادی جهانی تبدیل شد؟", E'\\n\\n## چطور بلک فرایدی از یک روز آمریکایی به رویدادی جهانی تبدیل شد؟\\n\\n'), "بلک فرایدی امروز؛ یک مناسبت با دو تاریخ متفاوت", E'\\n\\n## بلک فرایدی امروز؛ یک مناسبت با دو تاریخ متفاوت\\n\\n')),
    true
  ),
  updated_at = now(),
  has_unpublished_changes = false
where slug = 'black-friday-history'
  and status = 'published'
  and published_snapshot is not null
  and not (content like '%## پیش از حراج‌ها:%');
